async function api(path: string, method = 'GET', data?: any) {
    const r = await fetch('/api/v1' + path, { method, credentials: 'same-origin', headers: data instanceof FormData ? {} : data ? { 'Content-Type': 'application/json' } : {}, body: data instanceof FormData ? data : data ? JSON.stringify(data) : undefined });
    if (!r.ok) {
        const b = await r.json().catch(() => ({ detail: r.statusText }));
        throw new Error(typeof b.detail === 'string' ? b.detail : JSON.stringify(b.detail));
    }
    return r.json();
}
